const g=await glob({pattern:"data/orders/**/*"});const t={};const odd=[];for(const f of g.files){const c=(await read({path:f})).content;let o;try{o=JSON.parse(c)}catch(e){odd.push(f);continue}
if(o.status!=="paid"){if(String(o.status).trim().toLowerCase()==="paid")odd.push([f,o.status]);continue}
const s=o.items.reduce((a,i)=>a+i.qty*i.unitPriceCents,0);t[o.customer]=(t[o.customer]||0)+s}
return {odd,top:Object.entries(t).sort((a,b)=>b[1]-a[1])};

